#!/usr/bin/env bash
# =============================================================================
# DocFlow — патч по «Разбору второму» от 10.09.2026 (что осталось после правок)
#
#   1. Ложные колонки на тексте, выровненном по ширине.
#      Абзац больше не может стать шапкой таблицы (строка движка с
#      служебными словами на полстраницы, строка с денежной суммой). На актах
#      370/371 полоса «таблицы» начиналась с «3. Арендная плата…», и строка
#      «составляет 28,25… в том числе НДС 4,71» не попадала ни в одну зону.
#      Порядок слов внутри строки берётся из выдачи движка, а не из X.
#      Раскладка 04-ocr-layout.txt собирается на стороне Go: граница ячейки
#      ставится, только если просвет повторяется в соседней строке. Раскладка
#      сервиса surya остаётся в трассировке: 04-ocr-layout-engine.txt.
#
#   2. Маршрутизация. Документ компании с согласованием уходит в 1С без
#      главбуха, если прошёл проверку: тип сопоставлен с 1С и уверен,
#      обязательные поля не ниже порога, без НДС + НДС = итог (или позиции
#      сходятся с итогом), УНП компании найден на листе, контрагент найден в
#      справочнике по УНП. Не прошёл — к главбуху, в карточке подсвечены ровно
#      непрошедшие поля с причиной. Компании без согласования — как раньше.
#
#   3. Плотные таблицы. Сдвиг блока значений считается от графы к графе и
#      компенсируется; наименования привязываются к рядам значений по порядку
#      с подбором смещения; наименование, разрезанное пробелом, склеивается;
#      две слипшиеся числовые графы делятся; ряд номеров граф «1 2 3 … 8»
#      отбрасывается даже с подмешанным текстом; «0.24590 1.7277» больше не
#      склеивается в одно число.
#
#   4. Тип документа — только код из реестра, иначе unknown. Уверенность типа
#      считается (согласие правил и модели, название типа на листе) вместо
#      константы 0.85. «Акт пользования имуществом» опознаётся как act.
#
#   5. Стороны определяются по УНП компании, под которой загружен документ.
#
#   6. Заведомо неверные значения (УНП не из 9 цифр, невозможная дата…)
#      отклоняются: поле пустое, исходное значение и причина — в карточке.
#      Обрезанный УНП восстанавливается, если целиком есть в тексте один раз.
#      Дебет, совпадающий с кредитом, отклоняется.
#
#   7. Справочник контрагентов по УНП (таблица counterparties, миграция 0006):
#      наименование — синонимами, УНП для актов аренды — по наименованию.
#      При первом старте наполняется из уже выгруженных документов, дальше —
#      каждым документом, уходящим в 1С.
#
#   8. Сумма без НДС: из итога таблицы, из текста «в том числе НДС», третья
#      сумма из двух известных, сверка трёх сумм.
#
# Настройки (.env, все необязательные):
#   AUTO_PASS_ENABLED=true                     правило прохода мимо главбуха
#   AUTO_PASS_MIN_CONFIDENCE=0.75              порог уверенности полей
#   AUTO_PASS_MIN_TYPE_CONFIDENCE=0.75         порог уверенности типа
#   AUTO_PASS_REQUIRE_KNOWN_COUNTERPARTY=true  контрагент должен быть в справочнике
#   LAYOUT_FROM_WORDS=true                     раскладка из слов вместо сервиса
#   TABLE_DRIFT_FIX=true                       поправка сдвига граф
#   READ_ORDER=engine                          xy — прежняя сортировка по X
#
# Запуск:
#   cd /opt/docflow-deploy
#   bash patch-review2.sh             # проверить, применить, прогнать тесты, пересобрать
#   bash patch-review2.sh --dry-run   # только проверить версии файлов
#   bash patch-review2.sh --no-build  # применить без пересборки
#   bash patch-review2.sh --rollback  # вернуть последнюю резервную копию
# =============================================================================
set -euo pipefail

MODE=apply
FORCE=0
for a in "$@"; do
  case "$a" in
    --dry-run)  MODE=dry ;;
    --no-build) MODE=nobuild ;;
    --rollback) MODE=rollback ;;
    --force)    FORCE=1 ;;
    *) echo "неизвестный ключ: $a"; exit 2 ;;
  esac
done

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP=".backup-review2-${STAMP}"
say() { printf '\n\033[1m%s\033[0m\n' "$*"; }
err() { printf '\033[31m%s\033[0m\n' "$*" >&2; }

if [[ ! -d docflow/internal/recognize || ! -f docker-compose.yml ]]; then
  err "Запускать из каталога развёртывания (обычно /opt/docflow-deploy)."
  exit 1
fi
if docker compose version >/dev/null 2>&1; then DC="docker compose"; else DC="docker-compose"; fi

if [[ "$MODE" == rollback ]]; then
  last="$(ls -1d .backup-review2-* 2>/dev/null | sort | tail -n1 || true)"
  [[ -n "$last" ]] || { err "Резервных копий .backup-review2-* нет."; exit 1; }
  say "Откат из $last"
  (cd "$last" && find . -type f ! -name .added -print0 | xargs -0 -I{} cp -p {} ../{})
  if [[ -f "$last/.added" ]]; then
    while read -r f; do [[ -n "$f" ]] && rm -f "$f"; done < "$last/.added"
    rmdir docflow/internal/parties docflow/internal/recognize/testdata 2>/dev/null || true
  fi
  echo "  файлы возвращены. Таблица counterparties в базе остаётся (она ничему не мешает)."
  echo "  Пересборка: $DC build docflow-backend frontend && $DC up -d docflow-backend frontend"
  exit 0
fi

for t in tar base64 sha256sum; do
  command -v "$t" >/dev/null || { err "нужна утилита $t"; exit 1; }
done

say "Проверка версий файлов"
bad=0
while read -r want path; do
  [[ -n "$path" ]] || continue
  if [[ "$want" == NEW ]]; then
    if [[ -e "$path" ]]; then echo "  уже существует (будет перезаписан): $path"; fi
    continue
  fi
  if [[ ! -f "$path" ]]; then err "  нет файла: $path"; bad=1; continue; fi
  got="$(sha256sum "$path" | cut -d' ' -f1)"
  if [[ "$got" != "$want" ]]; then err "  отличается от архива 09.09: $path"; bad=1; fi
done <<'MANIFEST'
