5c24036d8cc4aba3074c2f72bf3de07e8be53c4b098c5b512befdea0d1f78306  docflow-frontend/src/styles.css
2de631fd9d47b610fa882f1c08c1ebd4b64b5eead02440384e939cdb2e894efa  docflow/internal/domain/models.go
