NEW  docflow/internal/parties/parties.go
NEW  docflow/internal/parties/parties_test.go
NEW  docflow/internal/recognize/readorder.go
NEW  docflow/internal/recognize/review2.go
NEW  docflow/internal/recognize/review2_table_test.go
NEW  docflow/internal/recognize/review2_test.go
NEW  docflow/internal/recognize/table_skew.go
NEW  docflow/internal/recognize/testdata/act371-flat.txt
NEW  docflow/internal/recognize/testdata/act371-words.tsv
NEW  docflow/internal/recognize/testdata/dense-invoice-words.tsv
NEW  docflow/internal/recognize/testdata/market-invoice-words.tsv
NEW  docflow/internal/storage/counterparties.go
NEW  docflow/internal/storage/counterparties_pg_test.go
NEW  docflow/internal/storage/migrations/0006_counterparties.sql
MANIFEST
if [[ $bad -ne 0 && $FORCE -ne 1 ]]; then
  err "Файлы на сервере не совпадают с версией, под которую сделан патч."
  err "Ничего не изменено. Пришлите эти файлы или запустите с --force (правки сервера в них будут потеряны)."
  exit 1
fi
echo "  ок"

if [[ "$MODE" == dry ]]; then
  say "Пробный прогон: проверка пройдена, ничего не изменено."
  exit 0
fi

say "Резервная копия: $BACKUP"
mkdir -p "$BACKUP"; : > "$BACKUP/.added"
while read -r want path; do
  [[ -n "$path" ]] || continue
  if [[ -f "$path" ]]; then
    mkdir -p "$BACKUP/$(dirname "$path")"; cp -p "$path" "$BACKUP/$path"
  else
    echo "$path" >> "$BACKUP/.added"
  fi
done <<'MANIFEST'
