PAYLOAD_B64
echo "  готово"

say "Тесты распознавания (в контейнере golang:1.22)"
if docker run --rm -v "$PWD/docflow":/src -w /src golang:1.22-bookworm \
     sh -c 'go test ./internal/recognize/ ./internal/parties/ ./internal/worker/ 2>&1 | tail -20'; then
  echo "  тесты прошли"
else
  err "Тесты не прошли. Откат: bash patch-review2.sh --rollback"
  exit 1
fi

if [[ "$MODE" == nobuild ]]; then
  say "Файлы разложены, пересборка пропущена."
  echo "  $DC build docflow-backend frontend && $DC up -d docflow-backend frontend"
  exit 0
fi

say "Пересборка бэкенда и фронта"
$DC build docflow-backend frontend
$DC up -d docflow-backend frontend
sleep 5
$DC logs --tail=40 docflow-backend | grep -Ei "migrat|справочник|error|panic" || true

say "Готово"
cat <<'DONE'
Что проверить на стенде:

  1. Лог бэкенда при старте: «справочник контрагентов наполнен из выгруженных
     документов, записей N». Проверка в базе:
       docker compose exec postgres psql -U docflow -c "select unp, name, synonyms from counterparties limit 20;"

  2. Перезагрузите акт 370 или 371. В трассировке:
       04a-zone-head.txt — строки абзаца в порядке листа, есть «в том числе НДС»;
       00-meta.json      — «зоны_найдены»: false, «авто_проход», «на_проверку_причины».
     В карточке: сумма без НДС заполнена, УНП арендодателя — из справочника.

  3. Счёт-фактура роддома (IMG_0217): 16 позиций, в каждой строке
     без НДС + НДС = с НДС, отдельная строка «Итого».

  4. Документ компании с согласованием, у которого всё сошлось, уходит в 1С
     без главбуха; остальные — к главбуху с блоком «Проверьте поля».
     Первый документ от нового контрагента всегда идёт человеку.

  5. Замер: доля документов в статусе needs_approval до и после на той же
     пачке.

Откат: bash patch-review2.sh --rollback
DONE
